async function refresh(){try{const r=await fetch('/api/state',{cache:'no-store'});const d:any=await r.json();if(!r.ok)throw new Error(d.error);setData(d);setError('')}catch(e:any){setError(e.message)}}
useEffect(()=>{const onMessage=(e:MessageEvent)=>{if(e.origin!==location.origin||e.source!==document.querySelector<HTMLIFrameElement>('.care-frame')?.contentWindow)return;if(e.data?.type==='kw-student-login')setView('studentLogin');if(e.data?.type==='kw-auth-refresh')refresh();};window.addEventListener('message',onMessage);return()=>window.removeEventListener('message',onMessage)},[]);
useEffect(()=>{if(new URLSearchParams(location.search).get('view')==='admin')setView('admin');refresh();try{setFavorites(JSON.parse(localStorage.getItem('kw-mentor-favorites')||'[]'))}catch{}},[]);
useEffect(()=>{setPage(1)},[field,query,dept,college,alumni,available,sort,savedOnly,view,format,supportStage,mentorCategory]);
