async function action(b:any,notify=true){setBusy(true);try{const r=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:data?.revision,...b})});const d:any=await r.json();if(!r.ok)throw new Error(d.error);if(notify)setToast(d.backup?.status==='success'?'저장하고 Google Drive 백업을 완료했습니다.':'저장했습니다. '+(d.backup?'Drive 백업은 관리 화면에서 상태를 확인하세요.':''));await refresh();return d}catch(e:any){setToast(e.message);throw e}finally{setBusy(false)}}
function nav(v:string){if(v!==view){setField('전체');setQuery('');setDept('전체 학과');setCollege('전체 대학');setFormat('전체 방식');setSavedOnly(false)}setView(v);setMobileNav(false);window.scrollTo({top:0,behavior:'smooth'})}
