const filteredPrograms=programs.filter(p=>(college==='전체 대학'||(p.department==='전체 학과'||p.department===college||mentors.some(m=>m.department===p.department&&m.college===college)))&&(field==='전체'||p.field===field)&&(format==='전체 방식'||p.format===format)&&(!query||[p.title,p.description,p.department].join(' ').includes(query))&&(dept==='전체 학과'||p.department==='전체 학과'||p.department===dept));
const mine=data?.applications||[];
