function mentorExport(){download('KW_멘토풀_'+new Date().toISOString().slice(0,10)+'.csv',csvText(mentors.map(m=>({'멘토 ID':m.id,'단과대학':m.college,'학과(부)':m.department,'멘토 분야':m.category,'성명':m.name,'소속기관':m.organization,'직급·직위':m.position,'연락처':m.phone||'','주요 경력·전문분야':m.expertise,'멘토링 가능 내용':m.description,'참여 가능 여부':m.availability,'연계 현황':m.connection,'동문 여부':m.alumni,'주 지원 분야':m.field,'비고':m.note||''}))))}
async function importFile(f:File){try{const bytes=await f.arrayBuffer();let t=new TextDecoder('utf-8').decode(bytes);if(t.includes('\uFFFD'))t=new TextDecoder('euc-kr').decode(bytes);const rows=parseCSV(t);setImporting({name:f.name,rows});setImportPreview(null)}catch(e:any){setToast(e.message)}}
async function submitApplication(e:any){e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));try{await action({action:'apply',form:{...f,consent:f.consent==='on',targetId:apply.target.id,type:apply.type}});setApply(null);nav('applications');setToast('학생성공디자인센터에 신청을 접수했습니다. 내 신청에서 처리 상태를 확인하세요.')}catch{}}
